input.content:
/* ============================================================
   CAREERS TABS — careers-tabs.module.css
   Source: .career-tabs-sec, .career-tabs-menu, .career-tab-item
   ============================================================ */

/* career-tabs-sec.overflow-hidden */
.section {
  background-color: transparent;
  padding-top: 20px;
  padding-bottom: 40px;
  display: block;
  overflow: hidden;
  position: relative;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 5%;
  padding-right: 5%;
}

/* career-sec2-outer */
.sectionOuter {
  display: flex;
  flex-flow: column;
  gap: 40px;
  align-items: center;
}

/* career-cont-center */
.contCenter {
  display: flex;
  flex-flow: column;
  align-items: center;
  gap: 0;
}

/* Header */
.header {
  text-align: center;
  max-width: 720px;
}

.heading {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.2;
  margin-top: 0;
  margin-bottom: 12px;
}

.subtitle {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 28px;
  text-align: center;
  margin: 0;
}

/* career-tabs-menu (.career-tabs-sc sticky) — grid 4 columns */
.tabNav {
  display: grid;
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  grid-auto-columns: 1fr;
  align-self: stretch;
  background-color: #def4ff;
  border-radius: 15px;
  margin-bottom: 0;
  margin-left: 0;
  margin-right: 0;
  padding: 10px;
  width: 100%;
}

/* career-tab-item */
.tabButton {
  background-color: transparent;
  border: none;
  border-radius: 0;
  padding: 15px 10px;
  cursor: pointer;
  text-decoration: none;
  text-align: center;
  transition: background-color 0.2s, box-shadow 0.2s;
}

/* career-tab-item.w--current */
.tabButtonActive {
  background-color: #fff;
  border-radius: 10px;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
}

/* career-tab-name */
.tabButtonText {
  color: #082753;
  text-align: center;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 18px;
  font-weight: 500;
  text-decoration: none;
  display: block;
}

/* Tab content wrapper */
.tabContent {
  width: 100%;
}

.tabPane {
  animation: fadeTabIn 0.22s ease-out;
}

@keyframes fadeTabIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── About & Culture sections ──
   career-tabs-about-sec.overflow-hidden / career-tabs-culture-sec.overflow-hidden */
.aboutSection {
  padding-top: 90px;
  padding-bottom: 40px;
  overflow: hidden;
}

.cultureSection {
  padding-top: 30px;
  padding-bottom: 60px;
  overflow: hidden;
}

/* career-about-tabc — 2-col grid */
.aboutGrid {
  display: grid;
  grid-column-gap: 50px;
  grid-row-gap: 50px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr;
  place-items: center;
}

/* career-culture-tabc */
.cultureGrid {
  display: grid;
  grid-column-gap: 50px;
  grid-row-gap: 50px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr;
  place-items: center;
  padding-top: 0;
  padding-bottom: 0;
}

/* career-about-images */
.imagesFlex {
  display: flex;
  flex-flow: row;
  gap: 16px;
  overflow: hidden;
  width: 100%;
  align-items: flex-start;
}

/* cabout-img */
.aboutImg {
  aspect-ratio: 2 / 3;
  object-fit: cover;
  border-radius: 20px;
  width: 48%;
  height: auto;
}

/* cabout-img.second-ig */
.aboutImgSecond {
  margin-top: 40px;
}

/* cculture-img */
.cultureImg {
  aspect-ratio: 2 / 3;
  object-fit: cover;
  border-radius: 20px;
  width: 48%;
  height: auto;
}

/* cculture-img.first-ig */
.cultureImgFirst {
  margin-top: 40px;
}

/* cabout-text */
.textColumn {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.tabHeading {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.2;
  text-align: left;
  margin-top: 0;
  margin-bottom: 16px;
}

/* max-width-small-3 */
.textInner {
  max-width: 500px;
}

.tabParagraph {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 28px;
  text-align: left;
  margin-bottom: 16px;
}

/* a-gulf-book.white-on-hover.padding-right-more */
.tabCta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem 3rem 0.75rem 1.5rem;
  line-height: 1.75rem;
  text-decoration: none;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
  margin-top: 16px;
  transition: opacity 0.2s;
}

.tabCta:hover {
  opacity: 0.9;
}

/* ── Benefits section ──
   career-tabs-benefits-sec.overflow-hidden */
.benefitsSection {
  background-image: url('/images/webflow/Rectangle-377.png');
  background-position: 50% 0;
  background-size: cover;
  padding-top: 60px;
  padding-bottom: 60px;
  overflow: hidden;
}

/* cbenefit-outer */
.benefitsOuter {
  display: flex;
  flex-flow: column;
  gap: 40px;
  align-items: center;
}

/* career-cont-center */
.benefitsCenter {
  display: flex;
  flex-flow: column;
  align-items: center;
  gap: 0;
}

.benefitsHeader {
  text-align: center;
}

/* career-dev-sec2-grid  → 4 cols */
.benefitsGrid {
  display: grid;
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr 1fr;
}

/* career-benefit-grid */
.benefitCard {
  background-color: #fff;
  border-radius: 20px;
  display: flex;
  flex-flow: column;
  justify-content: flex-start;
  align-items: flex-start;
  padding: 22px;
  position: relative;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
}

.benefitIcon {
  display: block;
  margin-bottom: 16px;
}

/* heading-3-blue */
.benefitTitle {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.53rem;
  font-weight: 700;
  margin-top: 0;
  margin-bottom: 12px;
}

.benefitText {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 28px;
  text-align: left;
  margin: 0;
}

/* ── Opportunities section ──
   career-tabs-opportunities-sec.overflow-hidden */
.opportunitiesSection {
  padding-top: 0;
  padding-bottom: 60px;
  overflow: hidden;
}

/* coppor-outer */
.opportunitiesOuter {
  display: flex;
  flex-flow: column;
  gap: 20px;
  align-items: center;
}

.opportunitiesCenter {
  display: flex;
  flex-flow: column;
  align-items: center;
}

.opportunitiesHeader {
  text-align: center;
}

/* opportunities-wrapper-large */
.jobWrapper {
  display: flex;
  flex-direction: column;
  gap: 15px;
  width: 100%;
  max-width: 850px;
  padding: 10px;
  overflow: hidden;
}

/* faq-item (.faq-item as job accordion) */
.jobItem {
  background-color: #fff;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  width: 100%;
  overflow: hidden;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
}

/* faq-toggle */
.jobToggle {
  background-color: transparent;
  border: none;
  width: 100%;
  cursor: pointer;
  text-align: left;
}

/* faq-title-wrapper */
.jobTitleRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px;
}

/* coppo-faq */
.jobMeta {
  width: 90%;
}

/* h6-heading-3 */
.jobTitle {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1.3;
  margin: 0 0 4px;
}

/* job-position */
.jobType {
  color: #05bafe;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 400;
  margin: 10px 0 0;
}

.jobArrow {
  flex-shrink: 0;
  transition: transform 0.22s ease;
}

.jobArrowOpen {
  transform: rotate(180deg);
}

/* faq-content */
.jobContent {
  padding: 0 24px 24px;
  border-top: 1px solid #f3f4f6;
}

/* paragraph-regular-5 / w-richtext */
.jobDescription {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 400;
  line-height: 26px;
  margin: 20px 0 16px;
}

.jobSectionLabel {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 8px;
  margin-top: 16px;
}

.jobList {
  list-style: disc;
  padding-left: 20px;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.jobListItem {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.6;
}

.fallbackNote {
  text-align: center;
  color: #6b7280;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 400;
  margin-top: 24px;
}

.fallbackLink {
  color: #019ae6;
  text-decoration: underline;
  font-weight: 600;
}

.fallbackLink:hover {
  color: #21cfff;
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .tabButtonText {
    font-size: 18px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding-top: 20px;
    padding-bottom: 40px;
  }

  /* career-tabs-sc.overflow-hidden hidden on mobile */
  .tabNavWrapper {
    display: none;
  }

  .aboutGrid,
  .cultureGrid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  /* For culture: images go below text — reorder */
  .cultureImagesOrder {
    order: 1;
  }

  .tabHeading {
    font-size: 34px;
  }

  .benefitsGrid {
    grid-template-columns: 1fr 1fr;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .tabNav {
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }

  .tabHeading {
    font-size: 28px;
  }

  .imagesFlex {
    flex-wrap: wrap;
  }

  .benefitsGrid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .jobTitleRow {
    padding: 16px 20px;
  }

  .jobContent {
    padding: 0 20px 20px;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding: 20px 0 40px;
  }

  .tabNav {
    grid-template-columns: 1fr 1fr;
    border-radius: 10px;
    padding: 6px;
    gap: 6px;
  }

  .tabButtonText {
    font-size: 14px;
  }

  .tabHeading {
    font-size: 1.5rem;
  }

  .aboutImg,
  .cultureImg {
    width: 47%;
  }

  .tabCta {
    width: 100%;
    justify-content: center;
  }
}

/* ============================================================
   CAREERS SELECTION — careers-selection.module.css
   Source: .career-sec2.overflow-hidden, .demodev-sec2-grid-inner
   ============================================================ */

/* career-sec2.overflow-hidden */
.section {
  background-color: transparent;
  padding-top: 20px;
  padding-bottom: 70px;
  display: block;
  overflow: hidden;
  position: relative;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 5%;
  padding-right: 5%;
}

/* career-sec2-outer */
.outer {
  display: flex;
  flex-flow: column;
  gap: 40px;
  justify-content: flex-start;
  align-items: center;
}

/* career-cont-center */
.header {
  display: flex;
  flex-flow: column;
  align-items: center;
  gap: 0;
  text-align: center;
}

.heading {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.2;
  margin-top: 0;
  margin-bottom: 0;
}

/* max-width-small-3.center-text */
.subtitleWrap {
  max-width: 500px;
  text-align: center;
}

.subtitle {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 28px;
  text-align: center;
  margin: 0;
}

/* career-dev-sec2-grid — 4 columns */
.grid {
  display: grid;
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  width: 100%;
}

/* demodev-sec2-grid-inner */
.card {
  background-color: #fff;
  border-bottom: 1px solid rgba(33, 207, 255, 0.3);
  border-right: 1px solid rgba(33, 207, 255, 0.3);
  border-radius: 0;
  padding: 30px 20px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  position: relative;
}

.cardIcon {
  display: block;
  margin-bottom: 20px;
  width: 48px;
  height: 48px;
}

/* heading-3-blue */
.cardTitle {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.53rem;
  font-weight: 700;
  margin-top: 0;
  margin-bottom: 12px;
}

.cardText {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 28px;
  text-align: left;
  margin: 0;
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding-top: 20px;
    padding-bottom: 40px;
  }

  .grid {
    grid-template-columns: 1fr 1fr;
  }

  .heading {
    font-size: 34px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 28px;
    line-height: 1.25;
  }

  .grid {
    grid-template-columns: 1fr;
    max-width: 520px;
    margin-left: auto;
    margin-right: auto;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-top: 16px;
    padding-bottom: 50px;
  }

  .heading {
    font-size: 1.5rem;
  }

  .subtitle {
    font-size: 0.9375rem;
  }

  .card {
    padding: 24px 16px;
  }
}

import Image from "next/image";
import styles from "./careers-selection.module.css";

const CARDS = [
  {
    icon: "/images/webflow/Layer_1-46.svg",
    title: "Structured Screening",
    text: "We review applications using a role-specific scorecard, focusing on proven results, clarity of thinking, and relevant experience — not just resumes.",
  },
  {
    icon: "/images/webflow/Layer_1-47.svg",
    title: "Work Sample Task",
    text: "Shortlisted candidates complete a practical assignment based on real client scenarios to evaluate execution quality, attention to detail, and decision-making.",
  },
  {
    icon: "/images/webflow/Layer_1-8.svg",
    title: "Live Problem Session",
    text: "Candidates participate in a focused discussion where we explore real challenges, communication style, and ownership mindset in action.",
  },
  {
    icon: "/images/webflow/Layer_1-49.svg",
    title: "Trial Project",
    text: "Final candidates may complete a short trial to demonstrate consistency, reliability, and alignment with Boldteq's performance standards.",
  },
];

export function CareersSelection() {
  return (
    <section className={styles.section}>
      <div className={styles.container}>
        <div className={styles.outer}>
          <div className={styles.header}>
            <h2 className={styles.heading}>Our Selection Process</h2>
            <div className={styles.subtitleWrap}>
              <p className={styles.subtitle}>
                We follow a structured, skills-first hiring process designed to identify professionals who can consistently deliver high-quality work in a real-world environment.
              </p>
            </div>
          </div>

          <div className={styles.grid}>
            {CARDS.map((card) => (
              <div key={card.title} className={styles.card}>
                <Image
                  src={card.icon}
                  alt={`${card.title} icon`}
                  width={48}
                  height={48}
                  className={styles.cardIcon}
                  loading="lazy"
                />
                <h3 className={styles.cardTitle}>{card.title}</h3>
                <p className={styles.cardText}>{card.text}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

