/* ============================================================
   SCOPE TABS — scope-tabs.module.css
   Source: .scope-tab-sec.new, .scope-tabs, .scope-tabs-menu
   ============================================================ */

/* scope-tab-sec.new */
.section {
  background-color: transparent;
  border-bottom-right-radius: 0;
  border-bottom-left-radius: 0;
  padding-top: 5rem;
  padding-bottom: 60px;
  display: block;
  position: relative;
}

/* container-large-3 */
.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 3%;
  padding-right: 3%;
}

/* scope-outer */
.scopeOuter {
  justify-content: flex-start;
  align-items: flex-start;
  display: block;
  position: relative;
}

/* scope-tabs — flex row: sidebar left, content right */
.scopeTabs {
  display: flex;
  flex-flow: row;
  gap: 30px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr;
  grid-auto-columns: 1fr;
  align-items: flex-start;
}

/* scope-tabs-menu — vertical sidebar */
.platformMenu {
  display: flex;
  flex-flow: column;
  gap: 10px;
  background-color: #fff;
